    pub fn record_internal_error(&self) {
        self.internal_errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_success(&self) {
        self.successful_requests.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn auth_failures(&self) -> u64 {
        self.auth_failures.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn rate_limited(&self) -> u64 {
        self.rate_limited.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn malformed_requests(&self) -> u64 {
        self.malformed_requests.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn oversized_bodies(&self) -> u64 {
        self.oversized_bodies.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn unauthorized(&self) -> u64 {
        self.unauthorized.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn not_found(&self) -> u64 {
        self.not_found.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn precondition_failed(&self) -> u64 {
        self.precondition_failed.load(std::sync::atomic::Ordering::Relaxed)
    }

